const app = {
  // append components by calling the following function
  displayComponent: (val, name, obj) => {
    app.elm('outputComponents').innerHTML += `<h4 class="m-0 m-4 capitalize">${val}</h4>
<hr class="pb-2">`

    // app.elm('outputComponents').innerHTML += `<div class="m-4 grid grid-cols-2 lg:grid-cols-4"></div>`
    app.elm('outputComponents').innerHTML += `<div class="m-4 grid grid-cols-2"></div>`

    for (i = 0; i < obj.length; i++) {
      let scroll = "app.scrollToEnd(0, parseInt(parseInt(app.elm('body').scrollHeight) - document.querySelector('[data-id=body] > :last-child').clientHeight))"
      if (obj[i].text === 'custom') {
        app.elm('outputComponents').querySelector('div:last-child').innerHTML += `<article class="p-0 m-0 mb-4 mr-4 text-center rounded-lg bg-gray-100 shadow-lg">
  <p>
    <a href="#">
      <img class="w-full rounded-lg" alt="add component" src="${obj[i].image}" onclick="document.querySelector('[data-customdialog]').setAttribute('open', true); app.updateHTMLStorage(activePage); this.closest('dialog').removeAttribute('open');">
    </a>
  </p>
</article>`
        break
      }
      if (obj[i].text === 'nav' || obj[i].text === 'notification') {
        scroll = "app.scrollToEnd(0, 0)"
      }
      app.elm('outputComponents').querySelector('div:last-child').innerHTML += `<article class="p-0 m-0 mb-4 mr-4 text-center rounded-lg bg-gray-100 shadow-lg">
    <p>
      <a href="#">
        <img class="w-full rounded-lg" alt="add component" src="${obj[i].image}" onclick="app.elm('body').innerHTML += ${name}[${i}].code; ${scroll}; app.updateEditable(); this.closest('dialog').removeAttribute('open');">
      </a>
    </p>
  </article>`
    }
  },

  scrollToEnd: (w, h) => {
    // scroll to end of body
    app.elm('body').scrollTo(w, h)
  },

  // add page
  loadPageList: () => {
    // apply the site name
    app.elm('sitename').value = appJSON.name

    // clear site pages before refresh
    app.elm('sitepages').innerHTML = ''

    // get pages data
    for (let i = 0; i < appJSON.pages.length; i++) {
      let val                          = appJSON.pages[i].name
      app.elm('title').value           = appJSON.pages[i].title
      app.elm('description').value     = appJSON.pages[i].description
      app.elm('author').value          = appJSON.pages[i].author
      app.elm('website').value         = appJSON.pages[i].website
      app.elm('analytics').value       = appJSON.pages[i].analytics
      app.elm('body').innerHTML        = appJSON.pages[i].content

      if (i === 0) {
        app.elm('sitepages').innerHTML += `
        <nav class="mb-4">
          <span>
            <a 
              class="cursor-pointer no-underline ${(i === activePage) ? 'text-blue-500' : 'text-current'}"
              onclick="app.activatePage(${i}); this.closest('dialog').removeAttribute('open');">
    
              ${val}.html
            </a>
          </span>
    
          <span>
            <a 
              class="cursor-pointer no-underline text-current"
              onclick="app.activatePage(${i}); document.querySelector('[data-pagesettings]').setAttribute('open', true);">
              
              <i class="fa fa-cog"></i>
            </a>
            <a 
              class="ml-2 cursor-pointer no-underline text-current"
              onclick="app.clonePage(${i});">
              
              <i class="fa fa-clone"></i>
            </a>
          </span>
        </nav>
      `
      } else {
        app.elm('sitepages').innerHTML += `
        <nav class="mb-4">
          <span>
            <a 
              class="cursor-pointer no-underline ${(i === activePage) ? 'text-blue-500' : 'text-current'}"
              onclick="app.activatePage(${i}); this.closest('dialog').removeAttribute('open');">
    
              ${val}.html
            </a>
          </span>
    
          <span>
            <a 
              class="cursor-pointer no-underline text-current"
              onclick="app.activatePage(${i}); document.querySelector('[data-pagesettings]').setAttribute('open', true);">
              
              <i class="fa fa-cog"></i>
            </a>
            <a 
              class="ml-2 cursor-pointer no-underline text-current"
              onclick="app.clonePage(${i});">
              
              <i class="fa fa-clone"></i>
            </a>
            <a 
              class="ml-2 cursor-pointer no-underline text-current"
              onclick="app.deletePage(${i});">
              
              <i class="fa fa-trash"></i>
            </a>
          </span>
        </nav>
      `
      }
    }
  },

  // add page
  addPage: () => {
    // first detect if user can clone a page
    if (!app.elm('title').value || !app.elm('description').value) {
      alert('Error: Website is missing the title or description meta information!')
      return false
    }

    // value for the new page name
    let val = prompt("What's the page's file name?").toLowerCase()

    // detect if page name already exists
    for (let i in appJSON.pages) {
      if (appJSON.pages[i].name === val) {
        alert('Operation aborted: Page name already exists!')
        return false
      }
    }

    // push page info to object
    let tempObj = {
      name:        val,
      title:       app.elm('title').value,
      description: app.elm('description').value,
      author:      app.elm('author').value,
      website:     app.elm('website').value,
      analytics:   app.elm('analytics').value,
      content:     ''
    }
    appJSON.pages.push(tempObj)

    // refresh pages list
    app.loadPageList()

    // refresh content
    app.activatePage(activePage)
  },

  // add page
  clonePage: index => {
    // value for the new page name
    let val = prompt("What's the page's file name?").toLowerCase()

    // detect if page name already exists
    for (let i in appJSON.pages) {
      if (appJSON.pages[i].name === val) {
        alert('Operation aborted: Page name already exists!')
        return false
      }
    }

    // clones the object
    let tempObj = {}
    for (let i in appJSON.pages[0]) {
      tempObj[`${i}`] = appJSON.pages[0][i]
    }

    // apply the new name to the cloned object
    tempObj.name = val

    // push cloned object to the pages object array
    appJSON.pages.push(tempObj)

    // refresh pages list
    app.loadPageList()
  },

  // delete page
  deletePage: i => {
    // delete page from object
    appJSON.pages.splice(i, 1)

    // refresh pages list
    app.loadPageList()

    // if user deletes the active page make the index the active page
    if (i === activePage) app.activatePage(0)
  },

  // make page active
  activatePage: index => {
    activePage = index

    let arr = [
      'title',
      'description',
      'author',
      'website',
      'analytics'
    ]
    for (let i of arr) {
      app.elm(`"${i}"`).setAttribute("onchange", `app.savePageData(${index});`)
      app.elm(`"${i}"`).setAttribute("onkeyup", `app.savePageData(${index});`)
    }

    app.elm('title').value       = appJSON.pages[index].title
    app.elm('description').value = appJSON.pages[index].description
    app.elm('author').value      = appJSON.pages[index].author
    app.elm('website').value     = appJSON.pages[index].website
    app.elm('analytics').value   = appJSON.pages[index].analytics
    app.elm('body').innerHTML    = appJSON.pages[index].content;

    // remove old active page color indicator
    app.elm('sitepages').querySelector('.text-blue-500').classList.add('text-current')
    app.elm('sitepages').querySelector('.text-blue-500').classList.remove('text-blue-500')
    app.elm('sitepages').querySelectorAll('nav > span:first-child > a')[activePage].classList.remove('text-current')
    app.elm('sitepages').querySelectorAll('nav > span:first-child > a')[activePage].classList.add('text-blue-500')
  },

  // get page data activates the current page
  savePageData: index => {
    appJSON.pages[index].title       = app.elm('title').value
    appJSON.pages[index].description = app.elm('description').value
    appJSON.pages[index].author      = app.elm('author').value
    appJSON.pages[index].website     = app.elm('website').value
    appJSON.pages[index].analytics   = app.elm('analytics').value
    appJSON.pages[index].content     = app.elm('body').innerHTML
  },
  
  // ajax function to get source of a file
  getFile: (url, callback) => {
    var xhr = new XMLHttpRequest()
    xhr.open("GET", url)
    xhr.send()
  
    xhr.onreadystatechange = (data) => {
      if (xhr.readyState !== 4) {
        return
      }
  
      if (xhr.status === 200) {
        callback(xhr.responseText)
      } else {
        console.warn("request_error")
      }
    }
  },

  // toggle theme
  toggleTheme: state => {
    // toggle theme
    if (state) {
      document.querySelector('html[data-theme]').setAttribute('data-theme', 'dark')
      document.querySelector('[data-id=previewElm][data-theme]').setAttribute('data-theme', 'dark')
      let icon = app.elm('themeicon')
      icon.classList.remove('fa-sun')
      icon.classList.add('fa-moon')
    } else {
      document.querySelector('html[data-theme]').setAttribute('data-theme', 'light')
      document.querySelector('[data-id=previewElm][data-theme]').setAttribute('data-theme', 'light')
      let icon = app.elm('themeicon')
      icon.classList.remove('fa-moon')
      icon.classList.add('fa-sun')
    }
    app.updatePreview()
  },

  // zooming and panning function
  initZoomPan: () => {
    // variables
    const userDevice    = document.querySelector('[data-device]')
    let canvas          = app.elm('previewElm')
    let canvasH         = parseFloat(canvas.clientHeight)
    let canvasW         = parseFloat(canvas.clientWidth / 2)
  
    // init panzoom
    let instance = panzoom(canvas, {
      bounds: true,
      boundsPadding: 0.1
    })
  
    centerCanvas = () => {
      canvasW = parseFloat(canvas.clientWidth)
      canvasH = parseFloat(canvas.clientHeight)
  
      // ratio for zoom
      let zoomRatio = 0.75
    
      // to center the canvas horizontally we first need to...
      // get half the body & canvas's width
      let bodyW   = parseFloat(document.body.clientWidth / 2)
      canvasW     = parseFloat(canvas.clientWidth / 2)
      // then add them together
      let initialXPos = parseFloat(parseFloat(bodyW) - parseFloat(canvasW) * zoomRatio)
    
      // to center the canvas vertically we first need to...
      // get the size of both the body and the canvas
      let bodyH   = parseFloat(document.body.clientHeight / 2)
      canvasH     = parseFloat(canvas.clientHeight / 2)
      canvasH     = canvasH / 4.5
      // then add them together
      let initialYPos = parseFloat(parseFloat(canvasH) - parseFloat(bodyH) * zoomRatio)
    
      // set initial zoom
      instance.zoomAbs(
        initialXPos, // initial x position
        initialYPos, // initial y position
        zoomRatio // initial zoom
      )
      instance.moveTo(initialXPos, initialYPos)
      return false
    }
    centerCanvas()
  
    // enable disable zoom/pan
    const zoomIcon = document.querySelector('[data-zoom]')
    zoomIcon.onclick = () => {
      if (zoomIcon.getAttribute('data-zoom') === 'true') {
        canvas.selection = false
        instance.pause()
        zoomIcon.innerHTML = '<i class="fa fa-light fa-magnifying-glass-minus"></i>'
        zoomIcon.setAttribute('data-zoom', false)
        app.elm('fill').classList.add('hidden')
      } else {
        canvas.selection = true
        instance.resume()
        zoomIcon.innerHTML = '<i class="fa fa-light fa-magnifying-glass-plus"></i>'
        zoomIcon.setAttribute('data-zoom', true)
        app.elm('fill').classList.remove('hidden')
      }
    }
  
    // rotate canvas
    app.elm('rotateCanvas').onclick = () => {
      canvasW = parseFloat(canvas.clientWidth)
      canvasH = parseFloat(canvas.clientHeight)
  
      canvas.style.width  = canvasH + 'px'
      canvas.style.height = canvasW + 'px'
      centerCanvas()
    }

    // reset canvas dimentions and center it
    resetCanvas = (w, h) => {
      canvasW = w
      canvasH = h

      if (canvasW > canvasH) {
        // landscape
        canvas.style.width  = canvasW + 'px'
        canvas.style.height = canvasH + 'px'
        centerCanvas()
        return false
      }
    
      canvas.style.width  = canvasH + 'px'
      canvas.style.height = canvasW + 'px'
      centerCanvas()
    }
  
    // toggle between mobile and desktop view
    userDevice.onclick = () => {
      if (userDevice.getAttribute('data-device') === 'mobile') {
        userDevice.setAttribute('data-device', 'tablet')
        userDevice.innerHTML = '<i class="fa fa-tablet"></i>'
        
        // reset canvas dimensions and center it
        // dimensions of iPad Mini used
        resetCanvas(1024, 768)
        return false
      }
      
      if (userDevice.getAttribute('data-device') === 'tablet') {
        userDevice.setAttribute('data-device', 'desktop')
        userDevice.innerHTML = '<i class="fa fa-desktop"></i>'
  
        // reset canvas dimensions and center it
        // 2012 macbook pro dimensions used
        resetCanvas(1440, 834)
        return false
      }

      if (userDevice.getAttribute('data-device') === 'desktop') {
        userDevice.setAttribute('data-device', 'mobile')
        userDevice.innerHTML = '<i class="fa fa-mobile"></i>'
  
        // reset canvas dimensions and center it
        // dimensions of Galaxy S8+ used
        resetCanvas(360, 740)
        return false
      }
    }
  },

  // update preview
  updatePreview: () => {
    let darkorlight = (appJSON.pages[activePage].theme) ? 'dark' : 'light'
    let code        = app.elm('body').innerHTML.toString()
    let callFuncs   = ''

    // fix event types for preview and export
    let eventTypes  = ['click', 'change', 'keyup', 'keydown']
    for (let i of eventTypes) {
      if (app.elm('body').querySelector(`[data-${i}]`)) {
        if (app.elm('body').querySelectorAll(`[data-${i}]`).length >= 0) {
          code = code.split(`data-${i}`).join(`on${i}`)
        }
      }
    }

    // handle share page if available
    if (app.elm('body').querySelector(`[data-shareto]`)) {
      callFuncs += `document.querySelectorAll("[data-shareto]").forEach(child => {
  let thisAttr = child.getAttribute("data-shareto").toLowerCase()
  let site = window.location.href;
  
  if (thisAttr === "facebook") {
    child.href = "https://www.facebook.com/sharer/sharer.php?u=" + site
  }
  if (thisAttr === "twitter") {
    child.href = "https://twitter.com/home?status=" + site
  }
  if (thisAttr === "googleplus") {
    child.href = "https://plus.google.com/share?url=" + site
  }
  if (thisAttr === "linkedin") {
    child.href = "https://www.linkedin.com/shareArticle?mini=true&url=" + site + "&title=&summary=&source="
  }
})
    `
    }

    let theScript   = `

    <script>
      ${callFuncs}</script>`

    let htmlCode  = `<!DOCTYPE html>
<html data-theme="${darkorlight}">
  <head>
    <title>${appJSON.name}</title>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1, shrink-to-fit=no">
    <meta name="description" content="${appJSON.description}">
    <link rel="stylesheet" href="css/style.css" />
  </head>
  <body>
    ${code}${(app.elm('body').querySelector("[data-shareto]")) ? theScript : ''}
  </body>
</html>`

    app.elm('previewElm').innerHTML = ""
    let frame = document.createElement("iframe")
    frame.setAttribute("data-id", "preview")
    frame.setAttribute("title", appJSON.name)
    frame.setAttribute("class", "w-full h-full overflow-auto")
    frame.setAttribute("sandbox", "allow-forms allow-modals allow-pointer-lock allow-popups allow-same-origin allow-scripts")
    app.elm('previewElm').appendChild(frame)
    let previewFrame = app.elm('preview')
    let preview      = previewFrame.contentDocument ||  previewFrame.contentWindow.document

    preview.open()
    preview.write(htmlCode)
    preview.close()

    // update json storage
    app.updateHTMLStorage(activePage)
  },

  // generate breadcrumb
  createBreadcrumb: el => {
    // update css styles for activeElm
    app.detectStyles()

    // get parents for breadcrumb
    let nodes = []
    let nodeSel = []
    let str = ''
    nodes.unshift(el.tagName.toString().toLowerCase())
    nodeSel.unshift('activeElm')
    while (el.parentNode) {
      str += '.parentElement'
      if (el.parentNode.getAttribute('data-id') === 'canvas') {
        // tree created
        break
      }
      nodes.unshift(el.parentNode.tagName.toString().toLowerCase())
      nodeSel.unshift('activeElm' + str)
      el = el.parentNode
    }

    // generate breadcrumb
    app.elm('crumblist').innerHTML = ""
    let counter = 1
    for (let i in nodes) {
      let dialogDetectStr = `let i = [...activeElm.parentElement.children].indexOf(activeElm); app.elm('dialogs').value = i; app.elm('dialogs').onchange();`
      let lastCodeStr = `${nodes[i]} <i class="fa fa-angle-right text-xs"></i> `
      let lastCode = `<li class="min-w-max pr-0">
      <button class="p-0 border-none bg-transparent text-current"
        onclick="activeElm = ${nodeSel[i]}; app.createBreadcrumb(activeElm); app.getTextAlignment(); app.elm('activeelmstyle').value = activeElm.className;">${nodes[i]}</button>
      </li>`
      let code = `<li class="min-w-max pr-0">
      <button class="p-0 border-none bg-transparent text-current"
        onclick="activeElm = ${nodeSel[i]}; app.createBreadcrumb(activeElm); app.getTextAlignment(); app.elm('activeelmstyle').value = activeElm.className;">${lastCodeStr}</button>
      </li>`

      if (nodes[i] === 'dialog') {
        lastCode = `<li class="min-w-max pr-0">
      <button class="p-0 border-none bg-transparent text-current"
        onclick="activeElm = ${nodeSel[i]}; app.createBreadcrumb(activeElm); app.getTextAlignment(); app.elm('activeelmstyle').value = activeElm.className; ${dialogDetectStr}">${nodes[i]}</button>
      </li>`
        code = `<li class="min-w-max pr-0">
      <button class="p-0 border-none bg-transparent text-current"
        onclick="activeElm = ${nodeSel[i]}; app.createBreadcrumb(activeElm); app.getTextAlignment(); app.elm('activeelmstyle').value = activeElm.className; ${dialogDetectStr}">${lastCodeStr}</button>
      </li>`
      }

      // detects if only 1 node is available
      if (nodes.length === 1) {
        app.elm('crumblist').innerHTML += lastCode
        break
      }

      // end of tree
      if (parseInt(1 + parseInt(i)) === nodes.length) {
        app.elm('crumblist').innerHTML += lastCode
        break
      }

      app.elm('crumblist').innerHTML += code
    }

    // show the active breadcrumb
    app.elm('crumblist').querySelector('li:last-child button').classList.add('text-blue-500')

    // update storage for page everytime this is called
    app.updateHTMLStorage(activePage)

    // detect if activeElm is body
    if (activeElm.hasAttribute('data-id')) {
      if (activeElm.getAttribute('data-id') === 'body') {
        app.elm('cloneElm').classList.add('hidden')
        app.elm('delElm').classList.add('hidden')
      }
    } else {
      app.elm('cloneElm').classList.remove('hidden')
      app.elm('delElm').classList.remove('hidden')
    }
  },

  // get text alignment
  getTextAlignment: () => {
    element = document.querySelector('[data-id=textalign]')
    currentAlignment = window.getComputedStyle(activeElm).getPropertyValue('text-align')
    let alignTypes = ['center', 'end', 'inherit', 'initial', 'justify', 'left', 'revert', 'right', 'start', 'unset']

    // remove default alignment style
    element.querySelector('i').className = 'fa-solid'

    if (currentAlignment === 'start' || 'end' || 'left' || 'unset' || 'inherit' || 'initial') {
      element.querySelector('i').className = 'fa-solid fa-align-left'
    }
    if (currentAlignment === 'right') {
      element.querySelector('i').className = 'fa-solid fa-align-right'
    }
    if (currentAlignment === 'center') {
      element.querySelector('i').className = 'fa-solid fa-align-center'
    }
    if (currentAlignment === 'justify') {
      element.querySelector('i').className = 'fa-solid fa-align-justify'
    }
  },

  // easier way to query element for neater node
  elm: selector => {
    return document.querySelector(`[data-id=${selector}]`)
  },

  // trigger dialog visibility
  openDialog: index => {
    // first detect if there's even a dialog to open
    if (app.elm('body').querySelector('dialog')) {
      // hide all dialogs
      for (let e of app.elm('body').querySelectorAll('dialog')) {
        e.removeAttribute('open')
      }
      // hide all dialogs if no dialog is selected
      if (!index.value) return false

      // only open dialog that matches the current index value
      app.elm('body').querySelectorAll('dialog')[index.value].setAttribute('open', true)
      // then make that dialog the activeElem
      activeElm = app.elm('body').querySelectorAll('dialog')[index.value]
      app.createBreadcrumb(activeElm)
      // let i = [...activeElm.parentElement.children].indexOf(activeElm)
    }
  },

  // use contentEditable to edit text
  updateEditable: () => {
    const callEditorMenus = () => {
      // generate breadcrumb
      app.createBreadcrumb(activeElm)

      // grab active element's alignment
      app.getTextAlignment()

      // detect total amount of dialogs
      if (app.elm('body').querySelector('dialog')) {
        app.elm('dialogs').innerHTML = '<option value="">dialogs</option>'
        app.elm('body').querySelectorAll('dialog').forEach((child, i) => {
          app.elm('dialogs').innerHTML += `<option value="${i}">${i}${(child.hasAttribute('id') ? `#${child.id}` : '')}</option>`
        })
      }

      // get activeElm's css classes
      app.elm('activeelmstyle').value = activeElm.className

      // handle app navigation for customization
      app.elm('main').classList.add('hidden')
      app.elm('mainfooter').classList.add('hidden')
      app.elm('breadcrumb').classList.remove('hidden')
      app.elm('classes').classList.add('hidden')

      // scroll to active breadcrumb
      app.elm('crumblist').scrollTo(app.elm('crumblist').scrollWidth, 0)

      // detect heading
      const hTypes = ['h1', 'h2', 'h3', 'h4', 'h5', 'h6']
      for (let val of hTypes) {
      if (activeElm.tagName.toLowerCase() === val) {
          app.elm('activeHeading').value = activeElm.tagName.toLowerCase()
        }
      }

      // detect a target and role attributes
      if (activeElm.tagName.toLowerCase() === 'a') {
        if (activeElm.hasAttribute('target')) {
          app.elm('targetblank').checked = true
        } else {
          app.elm('targetblank').checked = false
        }
        if (activeElm.hasAttribute('role')) {
          app.elm('buttonrole').checked = true
        } else {
          app.elm('buttonrole').checked = false
        }
      }

      app.elm('editor').classList.remove('hidden')
      app.elm('canvas').classList.remove('bottom-0')
      app.elm('canvas').classList.add('bottom-16')

      // update storage
      app.updateHTMLStorage(activePage)
    }
    const targetClick = e => {
      activeElm = e.target
      callEditorMenus()
    }
    const targetCursor = e => {
      let range = document.getSelection().getRangeAt(0)
      activeElm = range.commonAncestorContainer.parentElement
      callEditorMenus()
    }

    document.querySelectorAll('[data-id=canvas] > *').forEach(child => {
      child.contentEditable = true

      child.onclick = (e) => targetClick(e)
    })

    app.elm('canvas').onkeyup = e => targetCursor(e)
    app.elm('canvas').onfocus = e => targetCursor(e)
    app.updateHTMLStorage(activePage)
  },

  // update active page storage
  updateHTMLStorage: index => {
    // update storage
    appJSON.pages[index].content = app.elm('body').innerHTML
  },

  // append clipboard to selector
  appendClipboard: () => {
    if (app.elm('activechildquery').value) {
      activeElm.querySelectorAll(`${app.elm('activechildquery').value}`).forEach((child) => {
        navigator.clipboard.readText().then((clipText) => {
          child.insertAdjacentHTML('beforeend', clipText)
        })
      })
      app.updateHTMLStorage(activePage)
      return false
    }
    navigator.clipboard.readText().then((clipText) => {
      activeElm.insertAdjacentHTML('beforeend', clipText)
    })
  },

  // prepend clipboard to selector
  prependClipboard: () => {
    if (app.elm('activechildquery').value) {
      activeElm.querySelectorAll(`${app.elm('activechildquery').value}`).forEach((child) => {
        navigator.clipboard.readText().then((clipText) => {
          child.insertAdjacentHTML('afterbegin', clipText)
        })
      })
      app.updateHTMLStorage(activePage)
      return false
    }
    navigator.clipboard.readText().then((clipText) => {
      activeElm.insertAdjacentHTML('afterbegin', clipText)
    })
  },

  // insert code into canvas from rich text editor
  outputHTML: tag => {
    let range = document.getSelection().getRangeAt(0)
    let selection = document.getSelection().toString()
    let elm = document.createElement(`${tag}`)
    elm.setAttribute('data-id', 'activeElement')

    let activateElm = () => {
      activeElm = app.elm('activeElement')
      if (activeElm.hasAttribute('data-id')) {
        activeElm.removeAttribute('data-id')
      }
      app.createBreadcrumb(activeElm)
      app.updateEditable()
      app.updateHTMLStorage(activePage)

      // update tailwind classes for the activeElm
      app.elm('activeelmstyle').value = activeElm.className
    }
    if (tag.toLowerCase() === 'copy') {
      navigator.clipboard.writeText(activeElm.outerHTML)

      // notify user that the element has been copied
      app.notification('element copied to clipboard', '')

      return false
    }
    if (tag.toLowerCase() === 'nav') {
      elm.className = 'p-4'
      ul = document.createElement(`ul`)
      list = document.createElement(`li`)
      if (!selection) {
        list.innerHTML = `Text`
      } else {
        list.textContent = selection
        range.deleteContents()
      }
      ul.appendChild(list)
      elm.appendChild(ul)
      range.insertNode(elm)
      activateElm()
      return false
    }
    if (tag.toLowerCase() === 'textsize') {
      elm = document.createElement(`span`)
      elm.className = app.elm('textsize').value
      if (!selection) {
        elm.innerHTML = `Text`
      } else {
        elm.textContent = selection
        range.deleteContents()
      }
      range.insertNode(elm)
      activateElm()
      return false
    }
    if (tag.toLowerCase() === 'hgroup') {
      h2 = document.createElement(`h2`)
      h3 = document.createElement(`h3`)
      if (!selection) {
        h2.textContent = 'An Attractive Title'
      } else {
        range.deleteContents()
        h2.textContent = selection
      }
      h3.textContent = 'More about the title'
      elm.appendChild(h2)
      elm.appendChild(h3)
      elm.setAttribute('data-id', 'activeElement')
      range.insertNode(elm)
      activateElm()
      return false
    }
    if (tag.toLowerCase() === 'image') {
      if (activeElm.tagName.toString().toLowerCase() === 'img') {
        let val = prompt('url of the image', activeElm.getAttribute('src'))
        if (!val) return false
        app.img2DataURL(`${val}`, function(uri) {
          activeElm.setAttribute('src', uri)
        })
        return false
      }
      elm = document.createElement(`img`)
      let val = prompt('url of the image')
      if (!val) return false
      elm.setAttribute('alt', 'Polyrise')

      // convert url to base64
      app.img2DataURL(`${val}`, function(uri) {
        elm.src = uri
      })
      elm.setAttribute('data-id', 'activeElement')
      range.commonAncestorContainer.parentElement.appendChild(elm)
      activateElm()
      return false
    }
    if (tag.toLowerCase() === 'video') {
      elm = document.createElement(`iframe`)
      elm.setAttribute('data-id', 'activeElement')
      elm.className = "w-full h-80"
      let val = prompt('url of the video')
      if (!val) return false
      elm.src = val
      range.insertNode(elm)
      activateElm()
      return false
    }
    if (tag.toLowerCase() === 'ul') {
      elm.className = "text-current"
      list = document.createElement(`li`)
      if (!selection) {
        list.textContent = ' '
      } else {
        list.textContent = selection
        range.deleteContents()
      }
      elm.appendChild(list)
      range.insertNode(elm)
      activateElm()
      return false
    }
    if (tag.toLowerCase() === 'ol') {
      elm.className = "text-current"
      list = document.createElement(`li`)
      if (!selection) {
        list.textContent = ' '
      } else {
        list.textContent = selection
        range.deleteContents()
      }
      elm.appendChild(list)
      range.insertNode(elm)
      activateElm()
      return false
    }
    if (tag.toLowerCase() === 'textarea') {
      elm.placeholder = 'Type here...'
      elm.className = 'h-40 resize-none'
      range.insertNode(elm)
      activateElm()
      return false
    }
    if (tag.toLowerCase() === 'checkbox') {
      elm = document.createElement(`input`)
      elm.type = 'checkbox'
      range.insertNode(elm)
      activateElm()
      return false
    }
    if (tag.toLowerCase() === 'searchfield') {
      elm = document.createElement(`input`)
      elm.type = 'search'
      elm.placeholder = 'Search...'
      range.insertNode(elm)
      activateElm()
      return false
    }
    if (tag.toLowerCase() === 'form') {
      elm = document.createElement(`form`)
      elm.className = 'p-4'
      elm.innerHTML = `<input type="text" placeholder="Name" required="" class="bg-white text-current">
      <input type="email" placeholder="Email" required="" class="bg-white text-current">
      <input type="tel" placeholder="Phone" required="" class="bg-white text-current">
      <button type="submit" class="border-0 rounded-full uppercase" style="background-color: #ff3366;">
        <span class="text-xs">send form</span>
      </button>`
      range.insertNode(elm)
      activateElm()
      return false
    }
    if (tag.toLowerCase() === 'article') {
      let articleCode = val => {
        return `<hgroup>
  <h2>${val}</h2>
  <h3>Sub-title for more details</h3>
</hgroup>

<p>
Lorem, ipsum dolor sit amet consectetur adipisicing elit. Ut et fugit odio vitae quisquam accusamus, dolor ipsa voluptatem perspiciatis! Dicta possimus culpa tempora repellendus accusamus, doloribus corporis harum accusantium minus.
</p>

<footer class="text-right">
  <a href="#" role="button">
    learn more
  </a>
</footer>`
    }
      if (!selection) {
        elm.innerHTML = articleCode('An Attractive Title')
      } else {
        elm.innerHTML = articleCode(selection)
        range.deleteContents()
      }
      elm.className = "mx-4"
      range.insertNode(elm)
      activateElm()
      return false
    }
    if (tag.toLowerCase() === 'text') {
      if (!selection) {
        elm = document.createTextNode('Text')
      } else {
        elm = document.createTextNode(selection)
        range.deleteContents()
      }
      range.insertNode(elm)
      activateElm()
      return false
    }
    if (tag.toLowerCase() === 'kbd') {
      elm = document.createElement('kbd')
      if (!selection) {
        elm.innerHTML = "text"
      } else {
        elm.innerHTML = selection
        range.deleteContents()
      }
      range.insertNode(elm)
      activateElm()
      return false
    }
    if (tag.toLowerCase() === 'accordion') {
      let val = ''
      elm = document.createElement('details')
      if (!selection) {
        val = 'Title'
      } else {
        val = selection
        range.deleteContents()
      }
      let code = `<summary>${val}</summary>
  <p>Lorem ipsum dolor, sit amet consectetur adipisicing elit. Qui officia animi repellendus nihil, voluptas sed quos distinctio nemo aut, veritatis earum illo nesciunt sunt recusandae tenetur nisi! A, veritatis fugiat?</p>`
      elm.innerHTML = code
      range.insertNode(elm)
      activateElm()
      return false
    }
    if (tag.toLowerCase() === 'icon') {
      elm = document.createElement('i')
      range.deleteContents()
      elm.className = 'fa fa-rocket'
      range.insertNode(elm)
      activateElm()
      return false
    }
    if (tag.toLowerCase() === 'clone') {
      let val = prompt('How many times do you want to clone the element?')
      let parElm = activeElm.parentElement
      let code = activeElm.outerHTML.toString()
      for (i = 0; i < val; i++) {
        parElm.innerHTML += code
      }
      activeElm = parElm.querySelector(':last-child')
      app.createBreadcrumb(activeElm)
      app.updateHTMLStorage(activePage)
      return false
    }

    // toggle tag for heading
    if (!selection) {
      const hTypes = ['h1', 'h2', 'h3', 'h4', 'h5', 'h6']
      for (let val of hTypes) {
        if (tag.toLowerCase() === val) {
          // detect if heading has contents
          if (activeElm.textContent) {
            let daTag = activeElm.tagName.toLowerCase()
            let newTag = app.elm('activeHeading').value
            if (daTag === 'h1') {
              activeElm.outerHTML = activeElm.outerHTML
              .replace(/<h1/g, `<${newTag}`)
              .replace(/<\/h1>/g, `<${newTag}`)
            }
            if (daTag === 'h2') {
              activeElm.outerHTML = activeElm.outerHTML
              .replace(/<h2/g, `<${newTag}`)
              .replace(/<\/h2>/g, `<${newTag}`)
            }
            if (daTag === 'h3') {
              activeElm.outerHTML = activeElm.outerHTML
              .replace(/<h3/g, `<${newTag}`)
              .replace(/<\/h3>/g, `<${newTag}`)
            }
            if (daTag === 'h4') {
              activeElm.outerHTML = activeElm.outerHTML
              .replace(/<h4/g, `<${newTag}`)
              .replace(/<\/h4>/g, `<${newTag}`)
            }
            if (daTag === 'h5') {
              activeElm.outerHTML = activeElm.outerHTML
              .replace(/<h5/g, `<${newTag}`)
              .replace(/<\/h5>/g, `<${newTag}`)
            }
            if (daTag === 'h6') {
              activeElm.outerHTML = activeElm.outerHTML
              .replace(/<h6/g, `<${newTag}`)
              .replace(/<\/h6>/g, `<${newTag}`)
            }
          } else {
            let text = document.createTextNode('text')
            elm.appendChild(text)
            range.insertNode(elm)
          }
          return false
        }
      }
    }

    // detect if there's a selection
    if (selection) {
      if (tag.toLowerCase() === 'a') {
        let val = prompt('url for link to direct to')
        if (!val) return false
        elm.href = val
        if (app.elm('targetblank').checked) elm.setAttribute('target', '_blank')
        if (app.elm('buttonrole').checked) elm.setAttribute('role', 'button')
        elm.appendChild(range.extractContents())
        range.insertNode(elm)
        activateElm()
        return false
      }

      // if parent element is null
      if (!range.commonAncestorContainer.firstElementChild) {
        elm.appendChild(range.extractContents())
        range.insertNode(elm)
        elm.setAttribute('data-id', 'activeElement')
        activateElm()
        return false
      }

      // otherwise detect if parent is the same so user can toggle bold/italic/etc
      if (range.commonAncestorContainer.childNodes.length > 0) {
        if (range.commonAncestorContainer.firstElementChild.tagName.toLowerCase() === tag.toLowerCase()) {
          range.deleteContents()
          range.insertNode(document.createTextNode(selection))
          activeElm = range.commonAncestorContainer
          app.createBreadcrumb(activeElm)
          app.updateEditable()
          return false
        }

        // if parent is not the same allow user to have option to have both bold and italic
        elm.appendChild(range.extractContents())
        range.insertNode(elm)
        activeElm = range.commonAncestorContainer.startContainer
        app.createBreadcrumb(activeElm)
        app.updateEditable()
      }

      return false
    }

    if (tag.toLowerCase() === 'a') {
      if (app.elm('crumblist').querySelector('li:last-child button').textContent === 'a') {
        let val = prompt('url for link to direct to', activeElm.getAttribute('href'))
        if (!val) return false
        activeElm.href = val
        if (app.elm('targetblank').checked) activeElm.setAttribute('target', '_blank')
        if (app.elm('buttonrole').checked) activeElm.setAttribute('role', 'button')
        return false
      }
      let val = prompt('url for link to direct to')
      if (!val) return false
      elm.href = val
      if (app.elm('targetblank').checked) elm.setAttribute('target', '_blank')
      if (app.elm('buttonrole').checked) elm.setAttribute('role', 'button')
    }
    let text = document.createTextNode('Text')
    if (tag.toLowerCase() === 'p' || tag.toLowerCase() === 'blockquote') {
      text = document.createTextNode('Lorem ipsum dolor, sit amet consectetur adipisicing elit. Qui officia animi repellendus nihil, voluptas sed quos distinctio nemo aut, veritatis earum illo nesciunt sunt recusandae tenetur nisi! A, veritatis fugiat?')
    }
    elm.appendChild(text)
    range.insertNode(elm)
    activateElm()
  },

  // delete element
  deleteElm: () => {
    if (app.elm('activechildquery').value) {
      activeElm.querySelectorAll(`${app.elm('activechildquery').value}`).forEach((child) => {
        child.remove()
      })
      app.createBreadcrumb(activeElm)
      return false
    }
    let tempElm = activeElm.parentElement
    activeElm.remove()
    activeElm = tempElm
    app.createBreadcrumb(activeElm)
  },

  // toggle text alignment
  alignText: e => {
    let elm = e.querySelector('i')

    if (elm.classList.contains('fa-align-left')) {
      elm.className = 'fa-solid fa-align-center'
      activeElm.style.textAlign = 'center'
      return false
    }
    if (elm.classList.contains('fa-align-center')) {
      elm.className = 'fa-solid fa-align-right'
      activeElm.style.textAlign = 'right'
      return false
    }
    if (elm.classList.contains('fa-align-right')) {
      elm.className = 'fa-solid fa-align-justify'
      activeElm.style.textAlign = 'justify'
      return false
    }
    if (elm.classList.contains('fa-align-justify')) {
      elm.className = 'fa-solid fa-align-left'
      activeElm.style.textAlign = 'left'
      return false
    }
  },

  // grab element colors
  grabColor: (e, type) => {
    let color = window.getComputedStyle(activeElm).getPropertyValue(type)
    color = tinycolor(color)
    color = color.toHexString()
    e.value = color
  },

  // grab activeElm attributes
  grabAttr: () => {
    // clear the attributes container
    app.elm('outputattr').innerHTML = ''
    app.elm('children').innerHTML = ''
    app.elm('outputqueryattributes').innerHTML = ''

    // display the element's attributes
    let index = ''
    app.outputAttributes(activeElm, index, 'outputattr')

    // if activeElm has no children
    if (activeElm.children.length === 0) {
      app.elm('activeelmchildren').classList.add('hidden')
      return false
    } else {
      // display the activeElm's children's attributes
      let query = activeElm.children
      app.elm('activeelmchildren').classList.remove('hidden')

      // create containers
      for (let i = 0; i < query.length; i++) {
        let tag = query[i].tagName.toLowerCase()
        let newActive = `activeElm = activeElm.querySelectorAll('${tag}')[${i}]; app.createBreadcrumb(activeElm); app.getTextAlignment(); app.grabAttr();`
        app.elm('children').innerHTML += `<button class="inline-block w-auto" onclick="${newActive}">
    ${tag}[${i}]
  </button>
  `
        app.elm('outputqueryattributes').innerHTML += `
        <h5 class="mt-10 capitalize">
          element query ${tag}[${i}]'s attributes
          <hr>
        </h5>
        <div data-id="activeelmchild${i}" class="mb-4"></div>
      `
        app.outputAttributes(query[i], i, `activeelmchild${i}`)
      }
    }
  },

  // grabs and outputs a selector's attributes
  outputAttributes: (selector, index, container) => {
    let str = (index === '') ? 'activeElm' : `activeElm.children[${index}]`
    selector = (index === '') ? activeElm : activeElm.children[index]

    let detectAttr = () => {
      let daAttr, daCode;
      let tag = selector.tagName.toLowerCase()

      // ignore grabbing the body's attributes
      if (selector.hasAttribute('data-id')) {
        if (selector.getAttribute('data-id') === 'body') {
          return false
        }
      }

      // append input types as select option if e is an input
      if (tag === 'input') {
        let inputAttr = [
          'button', 
          'checkbox', 
          'color', 
          'date', 
          'datetime-local', 
          'email', 
          'file', 
          'hidden', 
          'image', 
          'month', 
          'number', 
          'password', 
          'radio', 
          'range', 
          'reset', 
          'search', 
          'submit', 
          'tel', 
          'text', 
          'time', 
          'url', 
          'week'
        ]
        let select = document.createElement('select')
        select.setAttribute('onchange', `${str}.setAttribute('type', this.value)`)
        for (let i of inputAttr) {
          let option = document.createElement('option')
          option.setAttribute('value', i)
          if (selector.getAttribute('type') === i) {
            option.setAttribute('selected', '')
          }
          option.textContent = i
          select.appendChild(option)
        }

        // append rest of the attributes
        for (let i = 0; i < selector.attributes.length; i++) {
          let nType = selector.attributes[i].nodeName
          if (nType === 'type') {
            nav = document.createElement('nav')
            daAttr = selector.attributes[i].nodeName
            daCode = select.outerHTML
          } else if (nType === 'min' || nType === 'max' || nType === 'step') {
            nav = document.createElement('nav')
            daAttr = selector.attributes[i].nodeName
            daCode = `<input 
    type="number" 
    value="${selector.attributes[i].nodeValue}" 
    onkeyup="${str}.setAttribute('${daAttr}', this.value)" 
    onchange="${str}.setAttribute('${daAttr}', this.value)">`
          } else {
            nav = document.createElement('nav')
            daAttr = selector.attributes[i].nodeName
            daCode = `<input 
    type="text" 
    value="${selector.attributes[i].nodeValue}" 
    onkeyup="${str}.setAttribute('${daAttr}', this.value)" 
    onchange="${str}.setAttribute('${daAttr}', this.value)">`
          }
          outputCode = `<ul>
              <li>
                <span class="my-2">
                  ${daAttr}
                </span>
              </li>
            </ul>
            <ul>
              <li>
                ${daCode}
              </li>
              <li>
                <button
                  onclick="${str}.removeAttribute('${daAttr}'); app.detectStyles();">
                    <i class="fa fa-trash"></i>
                </button>
              </li>
            </ul>`
          nav.innerHTML = outputCode
          app.elm(container).appendChild(nav)
        }
      } else {
        // append rest of the attributes
        for (let i = 0; i < selector.attributes.length; i++) {
          nav = document.createElement('nav')
          let daAttr = selector.attributes[i].nodeName
          daCode = `<input 
    type="text" 
    data-id="temp" 
    value="${selector.attributes[i].nodeValue}"
    onkeyup="${str}.setAttribute('${daAttr}', this.value)" 
    onchange="${str}.setAttribute('${daAttr}', this.value)">`
          outputCode = `<ul>
              <li>
                <span class="my-2">
                  ${daAttr}
                </span>
              </li>
            </ul>
            <ul>
              <li>
                ${daCode}
              </li>
              <li>
                <button
                  onclick="${str}.removeAttribute('${daAttr}'); app.detectStyles();">
                    <i class="fa fa-trash"></i>
                </button>
              </li>
            </ul>`
          nav.innerHTML = outputCode
          app.elm(container).appendChild(nav)
          if (daAttr.toString().toLowerCase() === 'style') {
            app.elm("temp").value = selector.getAttribute('style').toString()
          }
          app.elm("temp").removeAttribute('data-id')
        }
      }
    }
    
    detectAttr()
  },

  // grab element colors
  detectStyles: () => {
    // also grab attributes
    app.grabAttr()

    // detect background-color
    if (activeElm.style.backgroundColor) {
      app.elm('bgcolor').checked = true
    } else {
      app.elm('bgcolor').checked = false
    }
    // detect background-image url
    if (window.getComputedStyle(activeElm).getPropertyValue('background-image').includes("url") || activeElm.style.backgroundImage.includes("url")) {
      let str = activeElm.style.backgroundImage
      let imageURL = str.substring(5, str.length - 2)
      app.elm('bgimageurl').style.backgroundImage = `url("${imageURL}")`
      app.elm('checkbgimageurl').checked = true
    } else {
      app.elm('bgimageurl').style.backgroundImage = `url("data:image/svg+xml;base64,")`
      app.elm('checkbgimageurl').checked = false
    }
    // detect color
    if (activeElm.style.color) {
      app.elm('color').checked = true
    } else {
      app.elm('color').checked = false
    }
    // detect border-color
    if (activeElm.style.borderColor) {
      app.elm('bordercolor').checked = true
    } else {
      app.elm('bordercolor').checked = false
    }

    app.grabColor(app.elm('bgcolor'), 'background-color')
    app.grabColor(app.elm('color'), 'color')
    app.grabColor(app.elm('bordercolor'), 'border-color')
  },

  // toggle bg image
  toggleBGImage: e => {
    activeElm.setAttribute('data-id', 'theactiveelm')

    if (e.checked) {
      document.querySelector('[data-id=theactiveelm]').style.backgroundImage = app.elm('bgimageurl').style.backgroundImage
    } else {
      document.querySelector('[data-id=theactiveelm]').style.backgroundImage = ''
      app.elm('bgimageurl').style.backgroundImage = `url("data:image/svg+xml;base64,")`
    }

    activeElm.removeAttribute('data-id')
    
    setTimeout(() => {
      app.detectStyles()
    }, 100)
  },

  // change activeElm styles
  changeStyles: e => {
    if (app.elm('activechildquery').value) {
      let child = activeElm.querySelectorAll(`${app.elm('activechildquery').value}`)
      for (let i in child) {
        child[i].className = e.value
      }
    } else {
      activeElm.className = e.value
    }
  },

  // insert code into canvas from rich text editor
  setColor: (e, prop) => {
    if (prop.toLowerCase() === 'color') {
      activeElm.style.color = e
      e = document.querySelector('[data-id=color]')
      e.style.backgroundColor = e
    }
    if (prop.toLowerCase() === 'backgroundcolor') {
      activeElm.style.backgroundColor = e
      e = document.querySelector('[data-id=bgcolor]')
      e.style.backgroundColor = e
    }
    if (prop.toLowerCase() === 'bordercolor') {
      activeElm.style.borderColor = e
      e = document.querySelector('[data-id=bordercolor]')
      e.style.borderColor = e
    }
  },

  // share project
  shareProject: () => {
    // append preloader to show status of export
    document.body.innerHTML += `<div data-id="preloader" class="fixed inset-0 bg-white bg-opacity-75 backdrop-filter backdrop-blur-lg" style="z-index: 999999999;">
    <div class="p-4 h-full grid place-items-center">
      <div class="w-full text-center">
        <h2 class="p-0">Building The Project To Share</h2>

        <progress></progress>
      </div>
    </div>
  </div>`

    let cssLibrary = `@import url('https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.3.0/css/all.min.css');
@import url('https://cdnjs.cloudflare.com/ajax/libs/picocss/1.5.7/pico.classless.min.css');
@import url('https://michaelsboost.com/TailwindCSSMod/tailwind-mod.min.css');`
  
    let checkTheme  = (appJSON.theme) ? 'dark' : 'light'
    let picotheme   = `document.querySelector('html').setAttribute('data-theme', '${checkTheme}');`

    // detect the active page 
    let page = ''
    app.elm('sitepages').querySelectorAll('nav span:first-child a').forEach((child, i) => {
      if (child.classList.contains('text-blue-500')) {
        page = i
      }
    })

    // check for HTML code
    let elm = document.createElement('div')
    elm.innerHTML = appJSON.pages[page].content
    let code      = elm.innerHTML.toString()
    let callFuncs = ''

    // fix event types for preview and export
    let eventTypes  = ['click', 'change', 'keyup', 'keydown']
    for (let i of eventTypes) {
      if (elm.querySelector(`[data-${i}]`)) {
        if (elm.querySelectorAll(`[data-${i}]`).length >= 0) {
          code = code.split(`data-${i}`).join(`on${i}`)
        }
      }
    }
  
    // handle share page if available
    if (elm.querySelector(`[data-shareto]`)) {
      callFuncs += `document.querySelectorAll("[data-shareto]").forEach(child => {
  let thisAttr = child.getAttribute("data-shareto").toLowerCase()
  let site = window.location.href;
  
  if (thisAttr === "facebook") {
    child.href = "https://www.facebook.com/sharer/sharer.php?u=" + site
  }
  if (thisAttr === "twitter") {
    child.href = "https://twitter.com/home?status=" + site
  }
  if (thisAttr === "googleplus") {
    child.href = "https://plus.google.com/share?url=" + site
  }
  if (thisAttr === "linkedin") {
    child.href = "https://www.linkedin.com/shareArticle?mini=true&url=" + site + "&title=&summary=&source="
  }
})
    `
    }

    let theScript   = `
    
    <script>
      ${callFuncs}
    </script>`
  
    let data = {
      title        : app.elm('title').value,
      description  : app.elm('description').value,
      html         : `<!-- 
  Shared from Polyrise!
  Try Polyrise today at https://michaelsboost.com/Polyrise/
-->

${code} ${(elm.querySelector(`[data-shareto]`)) ? `${theScript}` : ''}`,
      css          : cssLibrary,
      javascript   : `// Shared from Polyrise: https://michaelsboost.com/Polyrise/ 
${picotheme}`,
      css_external : cssLibrary,
      editors: '000'
    }
    let JSONstring = JSON.stringify(data).replace(/"/g, "&quot;").replace(/'/g, "&apos;")
    
    let form = 
    '<form data-id="tempForm" action="https://codepen.io/pen/define" method="POST" target="_blank" style="display: none;">' + 
      '<input type="hidden" name="data" value=\'' + 
        JSONstring + 
        '\'>' + 
      '<button data-id="tempBtn">Create New Pen with Prefilled Data</button>' +
    '</form>'
  
    // append click then remove
    document.body.innerHTML += form
    elm.remove()
    app.elm('tempBtn').click()
    app.elm('tempForm').remove()

    // remove preloader
    app.elm('preloader').remove()
  },

  // function to load an image as base64
  loadFile: input => {
    // append preloader to show status of import
    document.body.innerHTML += `<div data-id="preloader" class="fixed inset-0 bg-white bg-opacity-75 backdrop-filter backdrop-blur-lg" style="z-index: 999999999;">
    <div class="p-4 h-full grid place-items-center">
      <div class="w-full text-center">
        <h2 class="p-0">Importing Project</h2>

        <progress></progress>
      </div>
    </div>
  </div>`

    let reader = new FileReader()
  
    reader.onload = e => {
      // grab file
      appJSON = JSON.parse(e.target.result)

      // place data into appropriate fields
      app.elm('sitename').value   = appJSON.name
      app.elm('scratchpad').value = appJSON.scratchpad
      app.elm('logo').src         = appJSON.logo

      // refresh pages list
      app.loadPageList()

      // always have index.html as the default page
      activePage = 0
      app.activatePage(activePage)

      // remove images if they already exist for exporting
      if (document.querySelector('[data-image]')) {
        document.querySelectorAll('[data-image]').forEach((child, index) => {
          child.remove()
        })
      }

      // convert create logo image sizes for manifest.json
      let imageArr = ['192', '256', '384', '512', app.elm('logo').width]
      for (let i of imageArr) {
        app.embedImage(app.elm('logo').src, i)
      }

      // clear assets
      app.elm('assets').innerHTML = ''

      // render assets
      for (let i in appJSON.assets) {
        app.elm('assets').innerHTML += `<article class="relative p-0 m-0 mb-4 mr-4 text-center rounded-lg bg-gray-100 shadow-lg">
          <p>
            <button 
              onclick="app.deleteAsset(this)"
              class="absolute top-0 right-0 m-4 bg-red-500 rounded-full border-0 w-auto px-4 py-2">
              <i class="fa fa-times"></i>
            </button>
            <img 
              onclick="app.copyAsset(this)"
              class="w-full rounded-lg cursor-pointer" 
              alt="image asset" 
              src="${appJSON.assets[i]}">
          </p>
        </article>`
      }

      // detect the theme
      app.toggleTheme(appJSON.theme)

      // remove preloader
      app.elm('preloader').remove()
    }
    reader.readAsText(input.files[0])
  },
  
  // function to load logo
  loadLogo: input => {
    let reader = new FileReader()
  
    reader.onload = e => {
      // grab file
      app.elm('logo').src = e.target.result

      // update logo in project file
      appJSON.logo = app.elm('logo').src

      // remove images if they already exist for exporting
      if (document.querySelector('[data-image]')) {
        document.querySelectorAll('[data-image]').forEach((child, index) => {
          child.remove()
        })
      }

      // convert create logo image sizes for manifest.json
      let imageArr = ['192', '256', '384', '512', app.elm('logo').width]
      for (let i of imageArr) {
        app.embedImage(app.elm('logo').src, i)
      }
    }
    reader.readAsDataURL(input.files[0])
  },

  // converts all images into a dataurl for easy saving
  img2DataURL: (url, callback) => {
    // Load images
    let image = new Image()
    image.src = url
    image.onload = function() {
      if (image.src.substring(0, 4).toLowerCase() === 'http') {
        let canvas = document.createElement("canvas")
        canvas.width = image.width
        canvas.height = image.height
        let ctx = canvas.getContext("2d")
        ctx.clearRect(0, 0, image.width, image.height)
        ctx.drawImage(this, 0, 0, image.width, image.height)
        callback(canvas.toDataURL("image/png"))
        canvas.remove()
        return false
      }

      callback(image.src)
    }
  },
  
  // Convert logo to png images for manifest.json
  embedImage: (source, size) => {
    // Load images
    let image = new Image()
    image.src = source
    image.onload = function() {
      let canvas = document.createElement("canvas")
      canvas.width = size
      canvas.height = size
      let ctx = canvas.getContext("2d")
      ctx.clearRect(0, 0, size, size)
      ctx.drawImage(this, 0, 0, size, size)
      let imageURL = canvas.toDataURL("image/png")
      let newImage = document.createElement("img")
          newImage.classList.add("hidden")
          newImage.setAttribute("data-image", "")
          newImage.src = imageURL

      // Append new image
      document.body.appendChild(newImage)
    }
  },

  // import assets
  importImageAsset: input => {
    let reader = new FileReader()
  
    reader.onloadend = e => {
      // store the asset inside the json array
      appJSON.assets.push(`${e.target.result}`)

      // now render the asset
      app.elm('assets').innerHTML += `<article class="relative p-0 m-0 mb-4 mr-4 text-center rounded-lg bg-gray-100 shadow-lg">
        <p>
          <button 
            onclick="app.deleteAsset(this)"
            class="absolute top-0 right-0 m-4 bg-red-500 rounded-full border-0 w-auto px-4 py-2">
            <i class="fa fa-times"></i>
          </button>
          <img 
            onclick="app.copyAsset(this)"
            class="w-full rounded-lg cursor-pointer" 
            alt="image asset" 
            src="${e.target.result}">
        </p>
      </article>
      `
    }
    // detect file type
    reader.readAsDataURL(input)
  },
  importAudioAsset: (input, type, name) => {
    let reader = new FileReader()
  
    reader.onloadend = e => {
      // store the asset inside the json array
      appJSON.assets.push(`${e.target.result}`)

      // now render the asset
      app.elm('assets').innerHTML += `<article class="relative p-0 m-0 mb-4 mr-4 text-center rounded-lg bg-gray-100 shadow-lg overflow-visible">
        <p class="pb-0">
          <button 
            onclick="app.deleteAsset(this)"
            class="absolute top-0 right-0 m-4 bg-red-500 rounded-full border-0 w-auto px-4 py-2 z-10">
            <i class="fa fa-times"></i>
          </button>
          <audio
            controls
            class="w-full mt-14">

            <source src="${e.target.result}" type="${type}">
          </audio>
        </p>
        <div 
          class="cursor-pointer py-2 text-center"
          onclick="app.copyAsset(this.parentElement.querySelector('p.pb-0 > audio > source'))">${name}</div>
      </article>
      `
    }
    // detect file type
    reader.readAsDataURL(input)
  },
  importVideoAsset: (input, type, name) => {
    let reader = new FileReader()
  
    reader.onloadend = e => {
      // store the asset inside the json array
      appJSON.assets.push(`${e.target.result}`)

      // now render the asset
      app.elm('assets').innerHTML += `<article class="relative p-0 m-0 mb-4 mr-4 text-center rounded-lg bg-gray-100 shadow-lg overflow-visible">
        <p>
          <button 
            onclick="app.deleteAsset(this)"
            class="absolute top-0 right-0 m-4 bg-red-500 rounded-full border-0 w-auto px-4 py-2 z-10">
            <i class="fa fa-times"></i>
          </button>
          <video
            controls
            class="w-full">

            <source src="${e.target.result}" type="${type}">
          </video>
        </p>
        <div 
          class="cursor-pointer py-2 text-center"
          onclick="app.copyAsset(this.parentElement.querySelector('p > video > source'))">${name}</div>
      </article>
      `
    }
    // detect file type
    reader.readAsDataURL(input)
  },

  // delete asset
  deleteAsset: e => {
    // remove the image
    e.closest('article').remove()

    // clear the assets array
    appJSON.assets = []    

    // refresh assets
    let elm = app.elm('assets').querySelectorAll('img')
    for (let i of elm) {
      appJSON.assets.push(i.src)
    }
  },

  // easy notifications
  notification: (val, img) => {
    let image
    if (img === '') {
      image = ''
    } else {
      image = `<img class="h-10 mr-4" src="${img}">`
    }
    app.elm('notifications').innerHTML += `<div>
      <article class="inline-block w-auto mt-0">
        <div>
          ${image}
          
          ${val}
        </div>
      </article>
    </div>`
    setTimeout(() => {
      document.querySelector('[data-id=notifications] > div:last-child').remove()
    }, 2000)
  },

  // copy image to clipboard
  copyAsset: type => {
    // detect if element is an audio element
    if (type.parentElement.tagName.toLowerCase() === 'audio') {
      if (activeElm.parentElement.tagName.toLowerCase() === 'audio') {
        // replace activeElm audio source
        activeElm.src = type.src
  
        // notify user the audio source has been changed
        app.notification('updated audio source', '')
  
        app.updateHTMLStorage(activePage)
        app.updateEditable()
        return false
      }

      // detect if breadcrumb is visible
      if (!app.elm('breadcrumb').classList.contains('hidden')) {
        if (app.elm('activechildquery').value) {
          activeElm.querySelectorAll(`${app.elm('activechildquery').value}`).forEach((child) => {
            child.insertAdjacentHTML('beforeend', type.parentElement.outerHTML.toString().split('onclick="app.copyAsset(this)"').join('').split('class="w-full mt-14"').join(''))
          })
          app.updateHTMLStorage(activePage)
          app.updateEditable()
          document.querySelector('[data-files]').removeAttribute('open')
          app.notification('element added to canvas', '')
          return false
        }
        activeElm.insertAdjacentHTML('beforeend', type.parentElement.outerHTML.toString().split('onclick="app.copyAsset(this)"').join('').split('class="w-full mt-14"').join(''))
        app.updateHTMLStorage(activePage)
        app.updateEditable()
        document.querySelector('[data-files]').removeAttribute('open')
        app.notification('element added to canvas', '')
        return false
      }

      // if activeElm is not an audio element the source to clipboard
      navigator.clipboard.writeText(type.outerHTML.toString().split('onclick="app.copyAsset(this)"').join('').split('class="w-full mt-14"').join(''))
  
      // notify user the audio source has been copied
      app.notification('copied to clipboard', '')
      return false
    }

    // detect if element is a video element
    if (type.parentElement.tagName.toLowerCase() === 'video') {
      if (activeElm.parentElement.tagName.toLowerCase() === 'video') {
        // replace activeElm video source
        activeElm.src = type.src
  
        // notify user the audio source has been changed
        app.notification('updated video source', '')
  
        app.updateHTMLStorage(activePage)
        app.updateEditable()
        return false
      }

      // detect if breadcrumb is visible
      if (!app.elm('breadcrumb').classList.contains('hidden')) {
        if (app.elm('activechildquery').value) {
          activeElm.querySelectorAll(`${app.elm('activechildquery').value}`).forEach((child) => {
            child.insertAdjacentHTML('beforeend', type.parentElement.outerHTML.toString().split('onclick="app.copyAsset(this)"').join('').split('class="w-full"').join(''))
          })
          app.updateHTMLStorage(activePage)
          app.updateEditable()
          document.querySelector('[data-files]').removeAttribute('open')
          app.notification('element added to canvas', '')
          return false
        }
        activeElm.insertAdjacentHTML('beforeend', type.parentElement.outerHTML.toString().split('onclick="app.copyAsset(this)"').join('').split('class="w-full"').join(''))
        app.updateHTMLStorage(activePage)
        app.updateEditable()
        document.querySelector('[data-files]').removeAttribute('open')
        app.notification('element added to canvas', '')
        return false
      }

      // if activeElm is not an video element the source to clipboard
      navigator.clipboard.writeText(type.outerHTML.toString().split('onclick="app.copyAsset(this)"').join('').split('class="w-full"').join(''))
  
      // notify user the video source has been copied
      app.notification('copied to clipboard', '')
      return false
    }

    // detect if element settings is visible
    if (document.querySelector('[data-elmsettings]').hasAttribute('open')) {
      if (!app.elm('checkbgimageurl').checked) {
        // notify user the image has been copied
        app.notification('copied to clipboard', `${type.src}`)
        return false
      }
      
      // replace activeElm background-image source
      activeElm.style.backgroundImage = `url("${type.src}")`
      app.elm('bgimageurl').style.backgroundImage = `url("${type.src}")`
      app.updateHTMLStorage(activePage)
      app.updateEditable()

      // notify user the background-image source has been changed
      app.notification('updated background-image', `${type.src}`)

      // close assets after background-image has been updated
      document.querySelector('[data-files]').removeAttribute('open')
      app.detectStyles()
      return false
    }

    // detect if activeElm is an image
    if (activeElm.tagName.toLowerCase() === 'img') {
      // replace activeElm image source
      activeElm.src = type.src
      app.updateHTMLStorage(activePage)

      // notify user the image source has been changed
      app.notification('updated image source', `${type.src}`)
      document.querySelector('[data-files]').removeAttribute('open')

      app.updateEditable()
      return false
    }

    // detect if breadcrumb is visible
    if (!app.elm('breadcrumb').classList.contains('hidden')) {
      if (app.elm('activechildquery').value) {
        activeElm.querySelectorAll(`${app.elm('activechildquery').value}`).forEach((child) => {
          if (child.tagName.toLowerCase() === 'img') {
            child.src = type.src
          } else {
            child.insertAdjacentHTML('beforeend', type.outerHTML.toString().split('onclick="app.copyAsset(this)"').join('').split('class="w-full rounded-lg cursor-pointer"').join(''))
          }
        })
        app.updateHTMLStorage(activePage)
        app.updateEditable()
        document.querySelector('[data-files]').removeAttribute('open')
        app.notification('image added to canvas', '')
        return false
      }
      activeElm.insertAdjacentHTML('beforeend', type.outerHTML.toString().split('onclick="app.copyAsset(this)"').join('').split('class="w-full rounded-lg cursor-pointer"').join(''))
      app.updateHTMLStorage(activePage)
      app.updateEditable()
      document.querySelector('[data-files]').removeAttribute('open')
      app.notification('image added to canvas', '')
      return false
    }

    // if activeElm is not an image copy the image source to clipboard
    navigator.clipboard.writeText(type.src)

    // notify user the image has been copied
    app.notification('copied to clipboard', `${type.src}`)
  },
  
  // export json
  exportJSON: () => {
      // append preloader to show status of import
      document.body.innerHTML += `<div data-id="preloader" class="fixed inset-0 bg-white bg-opacity-75 backdrop-filter backdrop-blur-lg" style="z-index: 999999999;">
      <div class="p-4 h-full grid place-items-center">
        <div class="w-full text-center">
          <h2 class="p-0">Exporting Project</h2>
  
          <progress></progress>
        </div>
      </div>
    </div>`

    let blob = new Blob([JSON.stringify(appJSON)], {type: "application/json"})
    saveAs(blob, `${appJSON.name.toString().toLowerCase().replace(/ /g,"")}-polyrise.json`)

    // remove preloader
    app.elm('preloader').remove()
  },

  // export zip file
  exportZip: () => {
    if (!app.elm('sitename').value || !app.elm('title').value || !app.elm('description').value || !app.elm('author').value) {
      alert('Error: Cannot cancelled! Reason: "Missing some metadata!"')
      return false
    }

    // append preloader to show status of export
    document.body.innerHTML += `<div data-id="preloader" class="fixed inset-0 bg-white bg-opacity-75 backdrop-filter backdrop-blur-lg" style="z-index: 999999999;">
    <div class="p-4 h-full grid place-items-center">
      <div class="w-full text-center">
        <h2 class="p-0">Compressing Project Files</h2>

        <progress></progress>
      </div>
    </div>
  </div>`

    let manifestJSONCode = `{
"theme_color":      "hsl(207, 31%, 11%)",
"background_color": "hsl(207, 31%, 11%)",
"display":      "standalone",
"start_url":    "./index.html",
"lang":         "en-US",
"name":         "${appJSON.name}",
"short_name":   "${appJSON.name}",
"description" : "${appJSON.description}",
"icons": [
  {
    "src":     "./imgs/icon-192x192.png",
    "sizes":   "192x192",
    "type":    "image/png",
    "purpose": "any"
  },
  {
    "src":     "./imgs/icon-256x256.png",
    "sizes":   "256x256",
    "type":    "image/png",
    "purpose": "any"
  },
  {
    "src":     "./imgs/icon-384x384.png",
    "sizes":   "384x384",
    "type":    "image/png",
    "purpose": "any"
  },
  {
    "src":     "./imgs/icon-512x512.png",
    "sizes":   "512x512",
    "type":    "image/png",
    "purpose": "maskable"
  }
]
}`

    // join font awesome library into users new project
    JSZipUtils.getBinaryContent("zips/font-awesome.zip", function(err, data) {
      if (err) {
        throw err // or handle err
      }
  
      let zip = new JSZip(data)

      // save css libraries/frameworks
      zip.file("libraries/pico/pico.classless.min.css", cssObj.data[0])
      zip.file("libraries/tailwind/tailwind-mod.min.css", cssObj.data[1])
  
      let base64Content = app.elm('logo').src
      // base64 encoded data doesn't contain commas    
      let base64ContentArray = base64Content.split(",")
      // base64 content cannot contain whitespaces but nevertheless skip if there are!
      let mimeType = base64ContentArray[0].match(/[^:\s*]\w+\/[\w-+\d.]+(?=[;| ])/)[0]
  
      let logoType
      if (mimeType === 'image/png') {
        zip.file("imgs/logo.png", app.elm('logo').src.split('base64,')[1],{base64: true})
        logoType = 'png'
      }
      if (mimeType === 'image/jpeg') {
        zip.file("imgs/logo.jpeg", app.elm('logo').src.split('base64,')[1],{base64: true})
        logoType = 'jpeg'
      }
      if (mimeType === 'image/svg+xml') {
        zip.file("imgs/logo.svg", app.elm('logo').src.split('base64,')[1],{base64: true})
        logoType = 'svg'
      }

      // save images for manifest.json
      zip.file("imgs/icon-192x192.png", document.querySelectorAll('[data-image]')[0].src.split('base64,')[1],{base64: true})
      zip.file("imgs/icon-256x256.png", document.querySelectorAll('[data-image]')[1].src.split('base64,')[1],{base64: true})
      zip.file("imgs/icon-384x384.png", document.querySelectorAll('[data-image]')[2].src.split('base64,')[1],{base64: true})
      zip.file("imgs/icon-512x512.png", document.querySelectorAll('[data-image]')[3].src.split('base64,')[1],{base64: true})
      zip.file("imgs/logo.png",         document.querySelectorAll('[data-image]')[4].src.split('base64,')[1],{base64: true})

      let picotheme = (appJSON.theme) ? 'data-theme="dark"' : 'data-theme="light"'

      zip.file("css/style.css", `/* imports */
@import url('../libraries/pico/pico.classless.min.css');
@import url('../libraries/tailwind/tailwind-mod.min.css');
@import url('../libraries/font-awesome/css/all.min.css');`)

      // save assets
      for (let i = 0; i < appJSON.assets.length; i++) {
        base64Content = appJSON.assets[i]
        // base64 encoded data doesn't contain commas
        base64ContentArray = base64Content.split(",")
        // base64 content cannot contain whitespaces but nevertheless skip if there are!
        mimeType = base64ContentArray[0].match(/[^:\s*]\w+\/[\w-+\d.]+(?=[;| ])/)[0]

        let fileType = mimeType.substring(6, mimeType.length)

        // detect image file types
        if (mimeType.substring(5, 0) === 'image') {
          if (fileType === 'vnd.microsoft.icon') {
            fileType = 'ico'
          }
          if (fileType === 'svg+xml') {
            fileType = 'svg'
          }
        }

        // detect audio file types
        if (mimeType.substring(5, 0) === 'audio') {
          if (fileType === 'mpeg') {
            fileType = 'mp3'
          }
          if (fileType === 'ogg') {
            fileType = 'oga'
          }
          if (fileType === 'webm') {
            fileType = 'weba'
          }
          if (fileType === '3gpp') {
            fileType = '3gp'
          }
          if (fileType === '3gpp2') {
            fileType = '3g2'
          }
        }

        // detect video file types
        if (mimeType.substring(5, 0) === 'video') {
          if (fileType === 'x-msvideo') {
            fileType = 'avi'
          }
          if (fileType === 'ogg') {
            fileType = 'ogv'
          }
          if (fileType === 'mp2t') {
            fileType = 'ts'
          }
          if (fileType === '3gpp') {
            fileType = '3gp'
          }
          if (fileType === '3gpp2') {
            fileType = '3g2'
          }
        }

        zip.file(`assets/asset${i}.${fileType}`, appJSON.assets[i].split('base64,')[1],{base64: true})
      }

      // save all pages with their data
      for (let i = 0; i < appJSON.pages.length; i++) {
        let elm = document.createElement('div')
        elm.innerHTML = appJSON.pages[i].content
        let code      = elm.innerHTML.toString()
        elm.querySelectorAll('[src]').forEach((child) => {
          for (let index in appJSON.assets) {
            base64Content = appJSON.assets[index]
            // base64 encoded data doesn't contain commas
            base64ContentArray = base64Content.split(",")
            // base64 content cannot contain whitespaces but nevertheless skip if there are!
            mimeType = base64ContentArray[0].match(/[^:\s*]\w+\/[\w-+\d.]+(?=[;| ])/)[0]
    
            let fileType = mimeType.substring(6, mimeType.length)
    
            // detect image file types
            if (mimeType.substring(5, 0) === 'image') {
              if (fileType === 'vnd.microsoft.icon') {
                fileType = 'ico'
              }
              if (fileType === 'svg+xml') {
                fileType = 'svg'
              }
            }
    
            // detect audio file types
            if (mimeType.substring(5, 0) === 'audio') {
              if (fileType === 'mpeg') {
                fileType = 'mp3'
              }
              if (fileType === 'ogg') {
                fileType = 'oga'
              }
              if (fileType === 'webm') {
                fileType = 'weba'
              }
              if (fileType === '3gpp') {
                fileType = '3gp'
              }
              if (fileType === '3gpp2') {
                fileType = '3g2'
              }
            }
    
            // detect video file types
            if (mimeType.substring(5, 0) === 'video') {
              if (fileType === 'x-msvideo') {
                fileType = 'avi'
              }
              if (fileType === 'ogg') {
                fileType = 'ogv'
              }
              if (fileType === 'mp2t') {
                fileType = 'ts'
              }
              if (fileType === '3gpp') {
                fileType = '3gp'
              }
              if (fileType === '3gpp2') {
                fileType = '3g2'
              }
            }

            if (appJSON.assets[index] === child.src) {
              child.src = `assets/asset${index}.${fileType}`
            }
            code = elm.innerHTML.toString()
          }
        })
        let callFuncs = ''
    
        // fix event types for preview and export
        let eventTypes  = ['click', 'change', 'keyup', 'keydown']
        for (let i of eventTypes) {
          if (elm.querySelector(`[data-${i}]`)) {
            if (elm.querySelectorAll(`[data-${i}]`).length >= 0) {
              code = code.split(`data-${i}`).join(`on${i}`)
            }
          }
        }
    
        // handle share page if available
        if (elm.querySelector(`[data-shareto]`)) {
          callFuncs += `document.querySelectorAll("[data-shareto]").forEach(child => {
      let thisAttr = child.getAttribute("data-shareto").toLowerCase()
      let site = window.location.href;
      
      if (thisAttr === "facebook") {
        child.href = "https://www.facebook.com/sharer/sharer.php?u=" + site
      }
      if (thisAttr === "twitter") {
        child.href = "https://twitter.com/home?status=" + site
      }
      if (thisAttr === "googleplus") {
        child.href = "https://plus.google.com/share?url=" + site
      }
      if (thisAttr === "linkedin") {
        child.href = "https://www.linkedin.com/shareArticle?mini=true&url=" + site + "&title=&summary=&source="
      }
    })
        `
        }
    
        let theScript   = `
    
        <script>
          ${callFuncs}</script>`

        zip.file(`${appJSON.pages[i].name}.html`, `<!DOCTYPE html>
<html lang="en-US" ${picotheme}>
  <head>
    <title>${appJSON.pages[i].title}</title>
    <meta charset="utf-8">
    <meta name="description" content="${appJSON.pages[i].description}">
    <meta name="author" content="${appJSON.pages[i].author}">
    <meta name="viewport" content="width=device-width, initial-scale=1, shrink-to-fit=no">
    <link rel="manifest" href="manifest.json">
    <meta name="mobile-web-app-capable" content="yes">
    <meta name="apple-mobile-web-app-capable" content="yes">
    <meta name="application-name" content="${appJSON.name}">
    <meta name="apple-mobile-web-app-title" content="${appJSON.pages[i].title}">
    <meta name="apple-mobile-web-app-capable" content="yes">
    <meta name="apple-mobile-web-app-status-bar-style" content="black-translucent">
    <meta name="theme-color" content="hsl(207, 31%, 11%)">
    <meta name="msapplication-navbutton-color" content="hsl(207, 31%, 11%)">
    <meta name="msapplication-starturl" content="./index.html">
    <link rel="apple-touch-icon" href="imgs/logo.${logoType}">
    <link rel="icon" href="imgs/logo.${logoType}" type="image/x-icon" />
    <meta property="og:url"         content="${appJSON.pages[i].website}" />
    <meta property="og:type"        content="website" />
    <meta property="og:title"       content="${appJSON.pages[i].title}" />
    <meta property="og:description" content="${appJSON.pages[i].description}" />
    <link rel="stylesheet"    href="css/style.css">
  </head>
  <body>
  ${code} ${(elm.querySelector(`[data-shareto]`)) ? `${theScript}` : ''}
  </body>
</html>`)
        elm.remove()

        // save kodeWeave project file in export
        let savekWProject = () => {
          let element = document.createElement('div')
          element.innerHTML = appJSON.pages[i].content
          let kwCode      = element.innerHTML.toString()
          let callFuncs = ''
      
          // fix event types for preview and export
          let eventTypes  = ['click', 'change', 'keyup', 'keydown']
          for (let i of eventTypes) {
            if (element.querySelector(`[data-${i}]`)) {
              if (element.querySelectorAll(`[data-${i}]`).length >= 0) {
                kwCode = kwCode.split(`data-${i}`).join(`on${i}`)
              }
            }
          }
        
          // handle share page if available
          if (element.querySelector(`[data-shareto]`)) {
            callFuncs += `document.querySelectorAll("[data-shareto]").forEach(child => {
        let thisAttr = child.getAttribute("data-shareto").toLowerCase()
        let site = window.location.href;
        
        if (thisAttr === "facebook") {
          child.href = "https://www.facebook.com/sharer/sharer.php?u=" + site
        }
        if (thisAttr === "twitter") {
          child.href = "https://twitter.com/home?status=" + site
        }
        if (thisAttr === "googleplus") {
          child.href = "https://plus.google.com/share?url=" + site
        }
        if (thisAttr === "linkedin") {
          child.href = "https://www.linkedin.com/shareArticle?mini=true&url=" + site + "&title=&summary=&source="
        }
      })
          `
          }
      
          let theScript   = `
      
  <script>
    ${callFuncs}
  </script>`

          let kWProj = {
            "name": appJSON.name,
            "scratchpad": appJSON.scratchpad,
            "logo": appJSON.logo,
            "theme": appJSON.theme,
            "css": "both",
            "fontSize": 16,
            "autoupdate": false,
            "console": true,
            "pwa": false,
            "fontawesome": true,
            "title": appJSON.pages[i].title,
            "description": appJSON.pages[i].description,
            "version": "0.1",
            "author": appJSON.pages[i].author,
            "website": appJSON.pages[i].website,
            "analytics": appJSON.pages[i].analytics,
            "html": `${kwCode} ${(element.querySelector(`[data-shareto]`)) ? `${theScript}` : ''}`,
            "javascript": ""
          }
          zip.file(`${appJSON.pages[i].name}-kodeWeave.json`, JSON.stringify(kWProj))
          element.remove()
        }
        savekWProject()
      }

      zip.file("manifest.json", manifestJSONCode)

      // save Polyrise project file in export
      zip.file(`${appJSON.name.toString().toLowerCase().replace(/ /g,"")}-polyrise.json`, JSON.stringify(appJSON))
  
      let content = zip.generate({type:"blob"})
      saveAs(content, `${appJSON.name.toString().toLowerCase().replace(/ /g,"")}-polyrise.zip`)

      // remove preloader
      app.elm('preloader').remove()
      return false
    })

    return false
  },

  // commit new attribute
  commitAttr: elm => {
    // ignore grabbing the body's attributes
    if (elm.hasAttribute('data-id')) {
      if (elm.getAttribute('data-id') === 'body') {
        alert('Abandoned Operation! You cannot add an attribute to the body!')
        app.elm('attrname').value = ''
        app.elm('attrval').value = ''
        return false
      }
    }
    if (app.elm('attrname').value.toLowerCase().trim() === 'data-id') {
      alert('Abandoned Operation! You cannot add this attribute! Why? Polyrise relies heavily on this to function.')
      return false
    }
    elm.setAttribute(app.elm('attrname').value, app.elm('attrval').value)
    app.elm('attrname').value = ''
    app.elm('attrval').value = ''
    app.detectStyles()
  },

  // commit a new attribute to children array
  commitChildAttr: elm => {
    if (!app.elm('activechildquery').value) {
      alert('Error: Query css selector value is empty!')
      return false
    }

    // detect if the query is not available 
    if (!elm.querySelector(`${app.elm('activechildquery').value}`)) {
      alert('Error: Query not found!')
      app.elm('queryattrname').value = ''
      app.elm('queryattrval').value = ''
      return false
    }

    let childElms = elm.querySelectorAll(`${app.elm('activechildquery').value}`)
    childElms.forEach(child => {
      child.setAttribute(app.elm('queryattrname').value, app.elm('queryattrval').value)
    })
    app.elm('queryattrname').value = ''
    app.elm('queryattrval').value = ''
    app.detectStyles()
  },
  
  // clear the html of all activeElm's children
  clearChildrensHTML: () => {
    activeElm.setAttribute('data-id', 'temp')
    document.querySelectorAll('[data-id=temp] > *').forEach((child) => {
      child.innerHTML = ''
    })
    activeElm.removeAttribute('data-id')
    app.grabAttr()
  },

  // initalize application function
  init: () => {
    // init zooming and panning
    app.initZoomPan()

    // apply activeElm to canvas onload
    activeElm = app.elm('body')

    // append components
    app.displayComponent('navigation', 'navObj', navObj)
    app.displayComponent('hero', 'heroObj', heroObj)
    app.displayComponent('article', 'articleObj', articleObj)
    app.displayComponent('gallery', 'galleryObj', galleryObj)
    app.displayComponent('grids & containers', 'gridsObj', gridsObj)
    app.displayComponent('dialogs & notifications', 'dialogObj', dialogObj)
    app.displayComponent('form', 'formObj', formObj)
    app.displayComponent('maps', 'mapsObj', mapsObj)
    app.displayComponent('social', 'socialObj', socialObj)
    app.displayComponent('footer', 'footerObj', footerObj)
    app.displayComponent('custom', 'customObj', customObj)
    app.updateEditable()

    // easily image assets
    app.elm('loadasset').onchange = input => {
      for (let numbers in input.target.files) {
        let file = input.target.files[numbers]
        if (file.type.toString().substring(0, 6) === "image/") {
          if (file.type.toString().substring(0, 9) === "image/pdf") {
            app.notification("Polyrise doesn't support loading pdf's")
          } else {
            app.importImageAsset(file)
          }
        }
        if (file.type.toString().substring(0, 6) === "audio/") {
          app.importAudioAsset(file, file.type, file.name)
        }
        if (file.type.toString().substring(0, 6) === "video/") {
          app.importVideoAsset(file, file.type, file.name)
        }
      }
    }

    // activeElm query for child styling
    app.elm('activeelmstyle').onkeyup = () => {
      if (app.elm('activechildquery').value) {
        let child = activeElm.querySelectorAll(`${app.elm('activechildquery').value}`)
        for (let i in child) {
          child[i].className = app.elm('activeelmstyle').value
        }
      } else {
        activeElm.className = app.elm('activeelmstyle').value
      }
    }

    // remove images if they already exist for exporting
    if (document.querySelector('[data-image]')) {
      document.querySelectorAll('[data-image]').forEach((child, index) => {
        child.remove()
      })
    }

    // convert create logo image sizes for manifest.json
    let imageArr = ['192', '256', '384', '512', app.elm('logo').width]
    for (let i of imageArr) {
      app.embedImage(app.elm('logo').src, i)
    }

    // load in default values
    app.loadPageList()
    cssObj.id   = []
    cssObj.data = []
    let urls    = ["libraries/pico/pico.classless.min.css", "libraries/tailwind/tailwind-mod.min.css"]
    cssObj.id   = urls
    for (let i of urls) {
      app.getFile(i, (source) => {
        cssObj.data = [...cssObj.data, source]
      })
    }
  }
}

// check if FileReader API is available
if (!window.FileReader) {
  alert('File API & FileReader API not supported!')
}

// initialize application
app.init()